window.SECPREP_LANGS.en={"code":"en","label":"English","short":"EN","speech":["en-US","en-GB","en"],"ui":{"appSub":"SY0-701 · 5 domains","streak":"Streak <b>{n}</b> days","streak1":"Streak <b>1</b> day","tPractice":"Practice","tLearn":"Lessons","tScen":"Scenarios","tProgress":"Progress","heroTitle":"Practice a little every day.","heroBody":"{n} practice questions written to the five SY0-701 domains. You've seen {s} of them.","daily":"Daily 25","dailyDesc":"Mixed domains, weighted toward questions you've missed","exam":"Mock exam","examDesc":"90 questions · 90 minutes · score at the end","missed":"Review missed","missedDesc":"{n} to fix","all":"All {n}","allDesc":"Every question, shuffled, instant feedback","byDomain":"Practice by domain","qCount":"{n} questions","weight":"exam weight {w}","notStarted":"not started","pctCorrect":"{p}% correct","end":"End","back":"Back","next":"Next","finish":"Finish","listen":"Listen","stop":"Stop","correct":"Correct","notQuite":"Not quite · answer: ","results":"results","ofCorrect":"{c} of {t} correct","unanswered":"{n} unanswered","msgHigh":"Exam-ready range. Keep the streak going.","msgMid":"Close. Review the misses below and run it again tomorrow.","msgLow":"Study the lessons for your weakest domain, then retry.","byDomainRes":"By domain","reviewMisses":"Review your misses","youChose":"You chose: ","answer":"Answer","unansweredLbl":"Unanswered","backPractice":"Back to practice","retryMissed":"Retry the {n} missed","quizDaily":"Daily 25","quizExam":"Mock exam","quizMissed":"Review missed","quizAll":"All questions","quizDomain":"Domain {d}","quizRetry":"Retry missed","lessonsEyebrow":"Study guide","lessonsTitle":"Lessons","lessonsBody":"Read or listen to each domain, then drill it. Turn on Auto-read in Progress to hear every question too.","domain":"Domain","listenDomain":"Listen to whole domain","speed":"Speed","audioNA":"Audio isn't available on this device.","examTip":"Exam tip","drill":"Drill Domain {d} questions","scenEyebrow":"Live incident simulations","scenTitle":"Scenarios","scenBody":"Logs stream in real time while the narrator walks you through the situation. You make the call at each step, the way performance-based questions test you.","decisions":"{n} decisions","best":"best {s}/{t}","notPlayed":"not played","play":"Play","exit":"Exit","step":"Step {i}/{n}","live":"LIVE FEED","narrOn":"Narration on","narrOff":"Narration off","seeDebrief":"See debrief","nextStep":"Next step","debrief":"Debrief","debriefGood":"Clean response. You followed the process step by step.","debriefBad":"Replay it and watch the order: contain, preserve evidence, eradicate, recover, learn.","replay":"Replay","allScen":"All scenarios","progEyebrow":"Your progress · saved on this device","progTitle":"Progress","dayStreak":"day streak","answers":"answers","accuracy":"accuracy","focusLbl":"Focus next","focusNext":"Your weakest domain is D{d} {n}. Read its lessons, then drill it.","startLbl":"Getting started","startBody":"Answer at least 5 questions in a domain to see where to focus.","accByDomain":"Accuracy by domain","noAnswers":"no answers yet","recent":"Recent sessions","noSessions":"No sessions yet. Start with the Daily 25 on the Practice tab.","examFacts":"Exam facts: up to 90 questions, 90 minutes, passing score 750 on a 100–900 scale. Aim for 85%+ here before booking.","disclaimer":"These are original practice questions written to the official SY0-701 exam objectives. They are not actual exam questions. Not affiliated with or endorsed by CompTIA. CompTIA and Security+ are trademarks of CompTIA, Inc.","reset":"Reset all progress","resetConfirm":"Tap again to erase everything","settings":"Settings","language":"Language","voice":"Voice","voiceAuto":"Best available","autoRead":"Read questions and feedback aloud automatically","voiceHelp":"For the most natural voice: on iPhone, go to Settings › Accessibility › Spoken Content › Voices and download an Enhanced or Premium voice. On Android, open Settings › Text-to-speech and install Google's high-quality voices. Then pick it here.","testVoice":"Test voice","voiceSample":"Hey there! I'm your study coach. Let's take this one step at a time... and get you ready to pass Security Plus.","reminder":"Daily reminder","reminderTime":"Time","reminderOn":"Remind me every day","reminderTitle":"Time for your Security+ drill","reminderBody":"Ten minutes today keeps your streak alive. Your Daily 25 is ready.","reminderSaved":"Reminder set for {t} every day.","reminderOff":"Reminder turned off.","reminderDenied":"Notifications are blocked. Allow them in your phone settings.","privacy":"Privacy: your progress stays on this device. Nothing is collected or sent anywhere."},"voice":{"intro":["Okay, here's the next one.","Alright... let's see this one.","Here's a good one.","Let's keep going.","Ready? Here we go.","Take your time with this one."],"options":"Your options are:","option":"Option","correct":["Yes! That's exactly right.","Nice work, you got it!","Correct! Well done.","That's it. Great job.","Perfect. You nailed it."],"wrong":["Hmm... not quite.","Ooh, close, but no.","Not this time, and that's okay.","Almost. Let's look at why."],"answerIs":"The correct answer is","tip":"And here's an exam tip.","lessonStart":"Let's study","nextTopic":["Now, let's move on to","Next up,","Alright, next topic:"],"scenStart":["Okay. Stay calm, here's what's happening.","Listen closely. This is a live situation."],"score":"You scored {s} out of {t}.","great":"Great work today. See you tomorrow!","keep":"Good effort. Review your misses, and come back tomorrow."},"domains":{"1":"General Security Concepts","2":"Threats, Vulnerabilities & Mitigations","3":"Security Architecture","4":"Security Operations","5":"Security Program Management & Oversight"},"q":[[1,"A company posts signs warning that the parking lot is under video surveillance. What type of control are the signs?","Deterrent",["Detective","Corrective","Compensating"],"Signs discourage an attacker before they act. The cameras themselves would be detective; the signs are deterrent."],
[1,"An administrator hashes a downloaded file and compares it to the vendor's published hash. Which security goal does this support?","Integrity",["Confidentiality","Availability","Authorization"],"Matching hashes prove the file was not altered, which is integrity."],
[1,"Which mechanism provides non-repudiation for an email?","A digital signature",["Symmetric encryption","A salted hash","TLS between mail servers"],"A digital signature is created with the sender's private key, so the sender cannot credibly deny sending it."],
[1,"Which part of AAA records which resources a user accessed and for how long?","Accounting",["Authentication","Authorization","Attestation"],"Accounting tracks activity (logs, session time, data used). Authentication proves identity; authorization grants rights."],
[1,"In a Zero Trust architecture, which component decides whether a subject should be granted access to a resource?","Policy Engine",["Policy Enforcement Point","Implicit trust zone","Data plane gateway"],"The Policy Engine makes the decision; the Policy Administrator relays it; the Policy Enforcement Point carries it out."],
[1,"Which Zero Trust component sits in the data plane and actually allows or blocks the connection?","Policy Enforcement Point",["Policy Engine","Policy Administrator","Threat intelligence feed"],"The PEP is in the data plane and enforces the decision. The PE and PA live in the control plane."],
[1,"A fake cloud API key is planted in a code repository so that any use of it raises an alert. What is this called?","Honeytoken",["Honeynet","DNS sinkhole","Tarpit"],"A honeytoken is fake data (credentials, records) that should never be used, so any use signals compromise."],
[1,"Before patching a production database, the change request must describe how to restore the previous state if the patch fails. What is this?","Backout plan",["Maintenance window","Impact analysis","Allow list"],"A backout (rollback) plan defines how to return to the known-good state."],
[1,"Which change management element defines an approved time period when changes can be made with the least business impact?","Maintenance window",["Backout plan","Standard operating procedure","Change owner"],"Maintenance windows schedule changes for low-usage periods."],
[1,"Which of the following is a symmetric encryption algorithm?","AES",["RSA","ECC","Diffie-Hellman"],"AES uses one shared key. RSA and ECC are asymmetric; Diffie-Hellman is a key-exchange method."],
[1,"Which method lets two parties agree on a shared secret key across an untrusted network without sending the key itself?","Diffie-Hellman key exchange",["AES-256","SHA-256","HMAC"],"Diffie-Hellman (and ECDHE) derive a shared secret that is never transmitted."],
[1,"Why is a random salt added to each password before hashing?","To defeat precomputed rainbow table attacks",["To allow passwords to be decrypted later","To make hashing faster","To shorten the stored hash"],"A unique salt means identical passwords produce different hashes, so precomputed tables are useless."],
[1,"PBKDF2, bcrypt and Argon2 are examples of what?","Key stretching",["Key escrow","Tokenization","Steganography"],"Key stretching runs many rounds to make each password guess expensive."],
[1,"Which protocol lets a client check whether a single certificate is revoked in near real time?","OCSP",["CRL","CSR","Key escrow"],"OCSP queries a responder for one certificate. A CRL is a full downloaded list."],
[1,"A web server includes a time-stamped, CA-signed revocation response inside the TLS handshake. What is this?","OCSP stapling",["Certificate pinning","A wildcard certificate","Subject Alternative Name"],"With stapling the server fetches the OCSP response and attaches it, saving the client a lookup."],
[1,"A single certificate secures shop.example.com, mail.example.com and www.example.com. The certificate is issued to *.example.com. What type is it?","Wildcard certificate",["Self-signed certificate","Root certificate","Code-signing certificate"],"The asterisk covers any single-level subdomain. A SAN certificate lists specific names instead."],
[1,"Which hardware chip on a laptop motherboard stores keys used for full-disk encryption and secure boot measurements?","TPM",["HSM","CASB","KMS"],"A Trusted Platform Module is built into the device. An HSM is a separate appliance or card for high-volume key work."],
[1,"A certificate authority needs a tamper-resistant appliance to generate and protect its signing keys at high volume. What should it use?","HSM",["TPM","Secure enclave on a phone","Key escrow agent"],"Hardware Security Modules are purpose-built, often network-attached, key-protection devices."],
[1,"A payment system replaces card numbers with random values that map back to the real number only inside a secure vault. What is this?","Tokenization",["Hashing","Data masking","Steganography"],"Tokens have no mathematical relationship to the original; only the vault can map them back."],
[1,"Which technology provides a distributed, tamper-evident record of transactions that many parties can verify?","Blockchain (open public ledger)",["Certificate revocation list","Key escrow","Single sign-on"],"Each block is chained by hashes, so changing history is evident."],
[1,"A team compares its current controls against a framework to find what is missing. What is this activity?","Gap analysis",["Penetration test","Risk transfer","Tabletop exercise"],"A gap analysis measures the difference between the current state and the target state."],
[1,"A written security awareness policy is which category of control?","Managerial",["Technical","Physical","Detective"],"Policies and risk assessments are managerial (administrative) controls."],
[1,"A legacy system cannot be patched, so it is moved to an isolated VLAN with strict firewall rules. What type of control is the isolation?","Compensating",["Corrective","Deterrent","Directive"],"A compensating control provides alternate protection when the primary control cannot be used."],
[1,"Which physical control best prevents a vehicle from being driven into a building entrance?","Bollards",["Access control vestibule","Video surveillance","Motion-sensing lights"],"Bollards are short sturdy posts that stop vehicles."],
[1,"Which physical control allows only one person through at a time and stops tailgating?","Access control vestibule",["Bollards","Fencing","Pressure sensors"],"A vestibule (mantrap) has two doors; the second opens only after the first closes."],
[1,"An attacker hides exfiltrated data inside the pixels of image files posted online. What technique is this?","Steganography",["Tokenization","Obfuscated code","Key stretching"],"Steganography hides data inside other data so its presence is not obvious."],
[1,"To create a digital signature, the sender encrypts the message hash with which key?","The sender's private key",["The sender's public key","The recipient's public key","The recipient's private key"],"Anyone can verify with the sender's public key, but only the sender holds the private key."],
[1,"To send a message only the recipient can read using asymmetric encryption, which key encrypts it?","The recipient's public key",["The recipient's private key","The sender's private key","A shared session key from the CA"],"Data encrypted with the recipient's public key can only be decrypted with their private key."],
[1,"A user receives a security exception approved by management with an expiry date. Which process is this part of?","Change and exception management",["Incident response","Data sanitization","Penetration testing"],"Exceptions are documented, approved and time-limited deviations from policy."],
[2,"An email impersonating the CEO is sent only to the CFO asking for an urgent wire transfer. What is this?","Whaling",["Vishing","Smishing","Watering hole"],"Whaling targets high-value executives. Spear phishing targets specific people in general."],
[2,"A caller claims to be from the bank's fraud team and asks for a one-time passcode. What attack is this?","Vishing",["Smishing","Pharming","Typosquatting"],"Vishing is voice phishing over a phone call."],
[2,"A text message says a package is held and links to a fake delivery site. What is this?","Smishing",["Vishing","Whaling","Bluejacking"],"Smishing is SMS phishing."],
[2,"An attacker poses as a new contractor with a detailed backstory to convince staff to give them building access. Which technique is central here?","Pretexting",["Shoulder surfing","Typosquatting","Dumpster diving"],"Pretexting builds a fabricated scenario to make the request seem legitimate."],
[2,"An attacker registers examp1e.com to catch users who mistype example.com. What is this?","Typosquatting",["Domain hijacking","DNS poisoning","Watering hole"],"Typosquatting relies on users making typing mistakes."],
[2,"Attackers compromise an industry forum that engineers at a target company visit often. What attack is this?","Watering hole",["Whaling","Brand impersonation","Pretexting"],"A watering hole attack infects a site the target group trusts and visits."],
[2,"Attackers take over a supplier's real mailbox and send an invoice with new bank details. What is this?","Business email compromise",["Smishing","Typosquatting","Credential stuffing"],"BEC uses a real compromised or spoofed business account to redirect payments."],
[2,"Malware encrypts file shares and displays a demand for cryptocurrency. What type of malware is it?","Ransomware",["Logic bomb","Rootkit","Spyware"],"Ransomware denies access to data until a ransom is paid."],
[2,"Code inserted by a disgruntled admin deletes payroll records if his account is ever disabled. What is this?","Logic bomb",["Worm","Trojan","Keylogger"],"A logic bomb runs when a specific condition is met."],
[2,"Malware modifies the kernel to hide its processes and files from the operating system and antivirus. What is it?","Rootkit",["Adware","Worm","Bloatware"],"Rootkits operate at a deep level (kernel or firmware) to hide themselves."],
[2,"Malware spreads from host to host across the network by exploiting a service, with no user action. What is it?","Worm",["Trojan","Virus","Logic bomb"],"Worms self-propagate. Viruses need a user or host file to spread."],
[2,"A free 'PDF converter' works as advertised but also installs a remote access tool. What is it?","Trojan",["Worm","Rootkit","Ransomware"],"A Trojan disguises malicious code as legitimate software."],
[2,"An attack runs entirely in memory using PowerShell and leaves no executable on disk. What is it?","Fileless malware",["Logic bomb","Bloatware","Polymorphic virus on disk"],"Fileless malware abuses built-in tools and memory to avoid file-based detection."],
[2,"A login field receives the input ' OR 1=1 -- and the attacker is logged in. What vulnerability is this?","SQL injection",["Cross-site scripting","Directory traversal","Buffer overflow"],"The input changes the SQL query logic. Fix it with parameterized queries and input validation."],
[2,"A forum comment contains <script> code that runs in every visitor's browser. What is this?","Stored cross-site scripting",["SQL injection","CSRF","Server-side request forgery"],"Stored (persistent) XSS saves the script on the server and serves it to other users."],
[2,"A user logged in to their bank visits a malicious page that silently submits a transfer request to the bank. What attack is this?","Cross-site request forgery",["Cross-site scripting","Session replay","Clickjacking"],"CSRF abuses the browser's existing authenticated session. Anti-CSRF tokens prevent it."],
[2,"A program writes more data into a memory region than was allocated, overwriting the return address. What is this?","Buffer overflow",["Race condition","Integer underflow","Memory leak"],"Buffer overflows can lead to code execution. Bounds checking, ASLR and DEP help."],
[2,"An app checks a file's permissions, then opens it a moment later; an attacker swaps the file in between. What is this?","Race condition (TOCTOU)",["Buffer overflow","Directory traversal","Injection"],"Time-of-check to time-of-use flaws exploit the gap between check and use."],
[2,"A web request includes ../../../../etc/passwd in a parameter. What attack is being attempted?","Directory traversal",["SQL injection","XML injection","Command injection"],"Directory (path) traversal tries to read files outside the web root."],
[2,"A standard user exploits a service flaw and gains administrator rights. What is this?","Privilege escalation",["Lateral movement","Pass-the-hash","Pivoting"],"Vertical privilege escalation gives higher rights than intended."],
[2,"An attacker on a coffee-shop network intercepts and alters traffic between a user and a website. What is this?","On-path attack",["Replay attack","Downgrade attack","DNS amplification"],"An on-path (man-in-the-middle) attacker sits between two parties."],
[2,"An attacker sends forged replies mapping the gateway's IP address to the attacker's MAC address. What is this?","ARP poisoning",["DNS poisoning","MAC flooding","VLAN hopping"],"ARP poisoning redirects LAN traffic through the attacker."],
[2,"Users typing the bank's correct URL are sent to a fake site because a resolver's cache was altered. What happened?","DNS poisoning",["Typosquatting","ARP poisoning","Session hijacking"],"Corrupted DNS records point a correct name to a malicious IP. DNSSEC helps prevent it."],
[2,"Attackers send small DNS queries with the victim's spoofed IP to open resolvers, which send large responses to the victim. What is this?","Amplified DDoS (reflection)",["Smurf replay","SYN cookie attack","Bluesnarfing"],"Reflection and amplification multiply traffic toward the victim."],
[2,"An attacker tries Spring2026! against thousands of accounts, one attempt each, to avoid lockouts. What is this?","Password spraying",["Brute force","Credential stuffing","Rainbow table attack"],"Spraying uses a few common passwords across many accounts."],
[2,"Attackers use username/password pairs from another company's breach to log in to your site. What is this?","Credential stuffing",["Password spraying","Birthday attack","Dictionary attack"],"Stuffing reuses leaked credentials, exploiting password reuse. MFA mitigates it."],
[2,"An attacker finds two different inputs that produce the same hash value. What attack is this?","Birthday attack (collision)",["Downgrade attack","Replay attack","Pass-the-hash"],"Birthday attacks exploit probability to find hash collisions."],
[2,"An on-path attacker forces a client and server to negotiate an older, weaker TLS version. What is this?","Downgrade attack",["Replay attack","Collision attack","Session fixation"],"Disabling old protocol versions prevents downgrades."],
[2,"An attacker captures a valid authentication message and resends it later to gain access. What mitigates this?","Timestamps and nonces",["Longer passwords","Salting","Wildcard certificates"],"Replay attacks fail when each message is unique and time-bound."],
[2,"An attacker uses a captured NTLM hash, without cracking it, to authenticate to other Windows hosts. What is this?","Pass-the-hash",["Rainbow table attack","Golden ticket only","Credential stuffing"],"Pass-the-hash presents the hash itself as the credential."],
[2,"A vulnerability is being exploited before the vendor knows about it or has a patch. What is it called?","Zero-day",["Known CVE","End-of-life flaw","False positive"],"Zero-day means the defenders have had zero days to fix it."],
[2,"A well-funded group backed by a government maintains long-term covert access to a defense contractor. Which actor is this?","Nation-state (APT)",["Hacktivist","Unskilled attacker","Insider threat"],"Nation-state actors have high resources and sophistication and stay persistent."],
[2,"A group defaces a company's website to protest its environmental record. Which actor type is this?","Hacktivist",["Organized crime","Nation-state","Shadow IT"],"Hacktivists are driven by ideology or political causes."],
[2,"An employee sets up an unapproved cloud file-sharing account to work faster. What is this?","Shadow IT",["Insider sabotage","Hacktivism","Supply chain attack"],"Shadow IT is technology used without IT approval, creating unmanaged risk."],
[2,"Which threat actor most often uses ready-made tools found online with little skill?","Unskilled attacker",["Nation-state","Organized crime","Competitor"],"Unskilled attackers (script kiddies) rely on others' tools."],
[2,"Attackers compromise a software vendor's update server so customers install malware with a legitimate update. What is this?","Supply chain attack",["Watering hole","Typosquatting","Zero-day on the client"],"Supply chain attacks reach the target through a trusted vendor or provider."],
[2,"A rogue access point broadcasts the same SSID as the corporate network to capture logins. What is this?","Evil twin",["Bluejacking","Jamming","WPS attack"],"An evil twin impersonates a legitimate Wi-Fi network."],
[2,"An attacker silently copies contacts from a phone over Bluetooth. What is this?","Bluesnarfing",["Bluejacking","War driving","NFC skimming"],"Bluesnarfing steals data. Bluejacking only sends unsolicited messages."],
[2,"A user installs apps from a website instead of the official store, bypassing app review. What is this?","Sideloading",["Jailbreaking","Rooting","Tethering"],"Sideloading installs apps outside the official store. Jailbreaking removes OS restrictions."],
[2,"An attacker breaks out of a guest virtual machine and accesses the hypervisor. What is this?","VM escape",["Resource reuse","VM sprawl","Container drift"],"VM escape breaks isolation between guests and host."],
[2,"Logs show a user logging in from New York and, ten minutes later, from Singapore. What indicator is this?","Impossible travel",["Resource exhaustion","Out-of-cycle logging","Blocked content"],"The distance can't be covered in that time, which suggests stolen credentials."],
[2,"A new IoT camera is put on the network still using admin/admin. What vulnerability is this?","Default credentials (misconfiguration)",["Zero-day","Race condition","Weak cipher suite"],"Change default credentials during hardening."],
[2,"Which mitigation limits an attacker's ability to move from a compromised workstation to the database servers?","Network segmentation",["Full-disk encryption","Data masking","Code signing"],"Segmentation restricts lateral movement between zones."],
[2,"Disabling unused services, closing ports and removing default accounts on a server is called what?","Hardening",["Patching","Sandboxing","Decommissioning"],"Hardening reduces the attack surface."],
[2,"Which attack sends traffic with many spoofed source MAC addresses to fill a switch's table so it floods frames to all ports?","MAC flooding",["ARP poisoning","VLAN hopping","DNS amplification"],"A full CAM table makes the switch act like a hub. Port security mitigates it."],
[2,"A malicious app sends requests from the server to internal-only services, such as the cloud metadata endpoint. What vulnerability is this?","Server-side request forgery",["Cross-site scripting","Directory traversal","LDAP injection"],"SSRF makes the server issue requests on the attacker's behalf."],
[2,"Physical: someone follows an employee through a secure door without badging in. What is this?","Tailgating",["Shoulder surfing","Pretexting","Impersonation"],"Tailgating (piggybacking) is mitigated by vestibules and guards."],
[3,"In a SaaS model, who is responsible for patching the application?","The cloud provider",["The customer","Both equally","The customer's ISP"],"In SaaS the provider manages nearly everything; the customer manages users and data."],
[3,"In IaaS, who is responsible for patching the guest operating system?","The customer",["The cloud provider","The hypervisor vendor","Nobody; it is automatic"],"With IaaS the provider secures the physical layer and hypervisor; the customer handles the OS and up."],
[3,"Developers deploy functions that run only when triggered, with no servers to manage. What model is this?","Serverless",["IaaS","Virtual desktop infrastructure","On-premises"],"Serverless (function as a service) removes server management from the customer."],
[3,"An application is built as many small independent services that talk over APIs. What architecture is this?","Microservices",["Monolithic","Mainframe","Air-gapped"],"Microservices can be scaled and secured independently."],
[3,"What is a key security benefit of Infrastructure as Code?","Consistent, repeatable and reviewable configurations",["It removes the need for access control","It encrypts all data by default","It replaces firewalls"],"IaC templates can be version-controlled and scanned, which reduces configuration drift."],
[3,"Which technology separates the control plane from the data plane so the network can be managed centrally in software?","Software-defined networking",["Air gap","Spanning tree","NAT"],"SDN centralizes control and programs network devices."],
[3,"A network with critical controls has no physical or wireless connection to any other network. What is this?","Air-gapped",["Screened subnet","VLAN","Extranet"],"An air gap provides physical isolation."],
[3,"A water utility uses systems that monitor and control pumps across a wide area. What are they?","ICS/SCADA",["VDI","Serverless","CASB"],"SCADA systems control industrial processes and often run legacy, hard-to-patch software."],
[3,"Admins must connect to a hardened host first before reaching servers in a secure zone. What is that host?","Jump server",["Reverse proxy","Load balancer","Honeypot"],"A jump server (bastion host) is a controlled, monitored entry point."],
[3,"A device receives requests from internet users and forwards them to internal web servers, hiding the servers. What is it?","Reverse proxy",["Forward proxy","Jump server","NAT gateway only"],"A reverse proxy protects servers. A forward proxy acts on behalf of internal clients."],
[3,"Which device inspects HTTP traffic at layer 7 to block attacks like SQL injection and XSS?","Web application firewall",["Packet-filtering firewall","Load balancer","NIDS on a span port"],"A WAF understands web application traffic."],
[3,"If an inline security appliance fails and stops all traffic, how is it configured?","Fail-closed",["Fail-open","Active-active","Passive mode"],"Fail-closed favors security; fail-open favors availability."],
[3,"What is the main difference between an IPS and an IDS?","An IPS sits inline and can block; an IDS monitors and alerts",["An IDS can block; an IPS only alerts","An IPS works only on hosts","There is no difference"],"IDS is passive (often on a tap or SPAN port); IPS is inline."],
[3,"Which IPsec mode encrypts the entire original IP packet, including headers, for site-to-site VPNs?","Tunnel mode",["Transport mode","Aggressive mode","AH only"],"Tunnel mode wraps the whole packet in a new IP header. Transport mode protects only the payload."],
[3,"Which architecture combines SD-WAN and cloud-delivered security services for remote users?","SASE",["SCADA","SAML","SOAR"],"Secure Access Service Edge delivers network and security from the cloud."],
[3,"Which standard provides port-based network access control, often with a RADIUS server?","802.1X",["802.11ac","WPA2-PSK","SNMPv3"],"802.1X authenticates devices before the switch port or Wi-Fi association allows traffic."],
[3,"Customer records stored in a database on disk are in which data state?","Data at rest",["Data in transit","Data in use","Data in motion"],"Data at rest is stored. In transit is moving over a network. In use is in memory or being processed."],
[3,"Data in a nation's data center must follow that nation's laws. What is this concept?","Data sovereignty",["Data masking","Data classification","Data retention"],"Data sovereignty ties data to the laws where it resides."],
[3,"Which recovery site is fully equipped with current data and can take over almost immediately?","Hot site",["Warm site","Cold site","Mobile site"],"A hot site is ready to go; warm has equipment but needs data; cold is empty space."],
[3,"The business can tolerate losing at most 4 hours of data. Which metric is this?","Recovery point objective",["Recovery time objective","Mean time to repair","Mean time between failures"],"RPO is data-loss tolerance. RTO is how long until service is restored."],
[3,"A backup copies only data changed since the last full backup, and restore needs the full plus the latest one. What type is it?","Differential",["Incremental","Snapshot","Full"],"Differential grows until the next full. Incremental needs the full plus every incremental."],
[3,"Which power component provides short-term battery power so systems can shut down safely or bridge to a generator?","UPS",["PDU","Generator","Surge protector only"],"A UPS covers short outages. A generator covers long ones."],
[3,"Two load-balanced servers both handle traffic at the same time. What configuration is this?","Active-active",["Active-passive","Cold standby","Round-robin DNS only"],"In active-active all nodes serve traffic; in active-passive one waits to take over."],
[3,"Which network zone hosts public-facing servers between the internet and the internal network?","Screened subnet",["Intranet","Air-gapped zone","Management VLAN"],"A screened subnet (DMZ) isolates internet-facing services."],
[3,"Using more than one vendor or OS so one flaw doesn't take down everything is called what?","Platform diversity",["Capacity planning","Geographic dispersion","Load balancing"],"Diversity reduces common-mode failures."],
[3,"Which label system assigns data levels such as Public, Internal, Confidential and Restricted?","Data classification",["Data sovereignty","Data retention","Data masking"],"Classification drives how data is handled and protected."],
[3,"Showing only the last four digits of a card number on screen is an example of what?","Data masking",["Tokenization","Hashing","Encryption at rest"],"Masking hides part of the data from view."],
[3,"An attacker steals a laptop with full-disk encryption that is powered off. Which data state does the encryption protect?","Data at rest",["Data in use","Data in transit","Data in processing"],"FDE protects stored data while the device is off or locked."],
[3,"Embedded devices with a real-time operating system are hard to secure mainly because of what?","Limited patching and resources",["They have too much memory","They always use strong encryption","They cannot connect to networks"],"Embedded and RTOS devices often can't be patched easily or run security agents."],
[3,"Which device consolidates firewall, IPS, antivirus, content filtering and VPN in one appliance?","Unified threat management",["Load balancer","Jump server","SIEM"],"UTM appliances combine several security functions."],
[3,"What is the main security benefit of containerization?","Isolating applications and their dependencies from each other",["Encrypting all network traffic","Removing the need for patching","Replacing authentication"],"Containers package apps with dependencies and isolate them, though they share the host kernel."],
[3,"Which disaster recovery test fails production over to the backup site to prove it works?","Failover test",["Tabletop exercise","Walkthrough","Paper review"],"A failover test actually moves the workload."],
[4,"An organization defines the approved settings every new server must have before deployment. What is this?","Secure baseline",["Gap analysis","Risk register","Exception"],"Baselines are established, deployed and then monitored for drift."],
[4,"Which tool lets IT enforce passcodes, push apps and remotely wipe company phones?","Mobile device management",["CASB","SIEM","NAC"],"MDM centrally manages mobile devices."],
[4,"The company buys phones and lets employees use them for personal tasks too. What deployment model is this?","COPE",["BYOD","CYOD","VDI"],"Corporate-owned, personally enabled. CYOD lets users choose from an approved list; BYOD is personal devices."],
[4,"Which Wi-Fi security protocol replaces the pre-shared key handshake with SAE?","WPA3",["WPA2","WEP","WPS"],"SAE (Simultaneous Authentication of Equals) resists offline dictionary attacks."],
[4,"Which EAP method requires certificates on both the server and the client?","EAP-TLS",["PEAP","EAP-TTLS","LEAP"],"EAP-TLS uses mutual certificate authentication and is very strong."],
[4,"Analyzing source code for flaws without running the program is called what?","Static analysis (SAST)",["Dynamic analysis","Fuzzing","Penetration testing"],"Static analysis reviews code. Dynamic analysis tests the running application."],
[4,"Sending large volumes of random, malformed input to an application to find crashes is called what?","Fuzzing",["Static analysis","Code signing","Sandboxing"],"Fuzzing is a dynamic testing technique."],
[4,"Running a suspicious file in an isolated environment to observe its behavior is called what?","Sandboxing",["Hardening","Fuzzing","Tokenization"],"A sandbox keeps the file from affecting real systems."],
[4,"Which method proves that software came from the stated developer and has not been altered?","Code signing",["Obfuscation","Input validation","Fuzzing"],"Code signing uses a digital signature on the code."],
[4,"Hard drives from decommissioned servers must be reused internally. Which approach removes data while keeping the drive usable?","Wiping (overwriting)",["Degaussing","Shredding","Incineration"],"Degaussing and shredding destroy the drive. Overwriting sanitizes for reuse."],
[4,"What document proves a third party destroyed your media as agreed?","Certificate of destruction",["Chain of custody form","SLA","Attestation of compliance"],"Vendors provide a certificate after destruction."],
[4,"Which vulnerability scan logs in to hosts to find missing patches and local misconfigurations?","Credentialed scan",["Non-credentialed scan","Passive scan","Port scan only"],"Credentialed scans see more and give fewer false positives."],
[4,"A scanner reports a vulnerability that, on investigation, does not actually exist. What is this?","False positive",["False negative","True positive","True negative"],"A false negative is the dangerous opposite: a real flaw that is missed."],
[4,"What does CVSS provide?","A severity score for vulnerabilities",["A unique ID for each vulnerability","A list of exploited malware","A cloud security standard"],"CVSS rates severity from 0 to 10. CVE provides the identifier."],
[4,"Which system aggregates and correlates logs from many sources and alerts on suspicious patterns?","SIEM",["SOAR","DLP","NAC"],"SIEM collects and correlates logs. SOAR automates the response."],
[4,"Which tool runs playbooks automatically, such as isolating a host and resetting a password when an alert fires?","SOAR",["SIEM","IDS","Vulnerability scanner"],"Security Orchestration, Automation and Response executes response playbooks."],
[4,"Which technology detects and blocks sensitive data, such as card numbers, leaving through email or uploads?","DLP",["EDR","WAF","IPS"],"Data loss prevention inspects content for sensitive data."],
[4,"Which endpoint tool records process, file and network activity and can isolate a compromised host?","EDR",["Antivirus signature scanner","Host firewall only","DLP"],"Endpoint detection and response gives visibility and response actions on hosts. XDR extends this across more sources."],
[4,"Which tool alerts when a critical system file such as a Windows DLL changes unexpectedly?","File integrity monitoring",["NetFlow","DLP","Port scanner"],"FIM compares files against known-good hashes."],
[4,"Which DNS record lists the mail servers allowed to send email for a domain?","SPF",["DKIM","DMARC","MX"],"SPF lists authorized senders. DKIM signs messages. DMARC sets the policy and reporting."],
[4,"Which email standard adds a digital signature to message headers so receivers can verify the sending domain?","DKIM",["SPF","DMARC","S/MIME"],"DKIM signatures are verified with a public key published in DNS."],
[4,"Which email standard tells receivers what to do when SPF or DKIM checks fail and sends reports?","DMARC",["SPF","DKIM","STARTTLS"],"DMARC policy can be none, quarantine or reject."],
[4,"Which version of SNMP adds authentication and encryption?","SNMPv3",["SNMPv1","SNMPv2c","SNMP traps"],"v1 and v2c use plain-text community strings."],
[4,"Which port does LDAPS use by default?","636",["389","443","3389"],"LDAP is 389; LDAPS is 636."],
[4,"Which protocol and port should replace Telnet for secure remote command-line access?","SSH on port 22",["SSH on port 23","RDP on 3389","FTP on 21"],"Telnet (23) sends everything in clear text."],
[4,"Which protocol lets users sign in once with their corporate identity provider and access a third-party web app using XML assertions?","SAML",["OAuth","Kerberos","RADIUS"],"SAML federates authentication with XML assertions. OAuth is for authorization; OpenID Connect adds authentication on top of OAuth."],
[4,"A photo app asks permission to access your cloud drive without getting your password. Which standard handles this?","OAuth",["SAML","LDAP","TACACS+"],"OAuth grants delegated authorization using tokens."],
[4,"Permissions are assigned to job functions such as 'Nurse' or 'Accountant', and users get permissions by being placed in them. What model is this?","Role-based access control",["Mandatory access control","Discretionary access control","Rule-based access control"],"RBAC assigns rights to roles."],
[4,"Access is granted based on the user's department, device health, location and time. What model is this?","Attribute-based access control",["Role-based access control","Discretionary access control","Mandatory access control"],"ABAC evaluates many attributes per request."],
[4,"Labels like Secret and Top Secret are assigned and users cannot change permissions. What model is this?","Mandatory access control",["Discretionary access control","Role-based access control","Attribute-based access control"],"MAC is enforced by the system using labels and clearances."],
[4,"The owner of a file decides who can read it. What model is this?","Discretionary access control",["Mandatory access control","Rule-based access control","ABAC"],"DAC lets the owner set permissions."],
[4,"A password plus a fingerprint is which combination of factors?","Something you know and something you are",["Something you have and something you are","Two things you know","Somewhere you are and something you know"],"Fingerprints are biometric (something you are)."],
[4,"An authenticator app shows a 6-digit code that changes every 30 seconds. What is this?","TOTP",["HOTP","SMS OTP","Static PIN"],"Time-based one-time passwords change on a clock. HOTP changes on a counter."],
[4,"Admins receive elevated rights only for a set time when they request it. Which PAM feature is this?","Just-in-time permissions",["Password vaulting","Federation","Single sign-on"],"JIT access removes standing privileges."],
[4,"What is the correct order of the incident response process?","Preparation, detection, analysis, containment, eradication, recovery, lessons learned",["Detection, preparation, containment, analysis, recovery, eradication, lessons learned","Containment, detection, eradication, preparation, recovery, lessons learned","Preparation, containment, detection, recovery, eradication, lessons learned"],"Remember: prepare, detect, analyze, contain, eradicate, recover, learn."],
[4,"After confirming ransomware on one workstation, what should the responder do next?","Isolate the host from the network",["Reimage the host immediately","Pay the ransom","Write the lessons-learned report"],"Containment comes before eradication and recovery."],
[4,"Analysts proactively search for attackers that existing tools haven't alerted on. What is this?","Threat hunting",["Vulnerability scanning","Penetration testing","Tabletop exercise"],"Threat hunting assumes a breach and searches for it."],
[4,"Which item should be collected first according to the order of volatility?","CPU registers and cache",["Hard drive contents","Archived backups","Remote logs"],"Collect the most volatile data first: registers and cache, RAM, swap, disk, then remote and archive."],
[4,"Which document records every person who handled evidence, and when?","Chain of custody",["Legal hold","Certificate of destruction","Acceptable use policy"],"Chain of custody proves evidence integrity in court."],
[4,"Lawyers instruct IT to preserve all email related to a lawsuit and suspend deletion. What is this?","Legal hold",["E-discovery","Data retention policy","Chain of custody"],"A legal hold overrides normal retention and deletion."],
[4,"Which data source shows summaries of which IP addresses talked to which, how much and when, without full packet contents?","NetFlow",["Packet capture","Syslog from apps","Vulnerability scan"],"NetFlow provides metadata about traffic flows."],
[4,"Which Linux feature enforces mandatory access control policies on processes?","SELinux",["sudo","iptables","chmod"],"SELinux adds MAC labels on top of standard Linux permissions."],
[4,"Which control blocks users from reaching known malicious domains by refusing to resolve them?","DNS filtering",["DKIM","DHCP snooping","NAT"],"DNS filtering stops connections at the name-resolution step."],
[4,"Users must enter a code from an authenticator after a password, and access is granted only from managed devices. Which access approach is this?","Conditional access with MFA",["Single sign-on only","Discretionary access control","Federation without MFA"],"Conditional access evaluates context (device, location) along with MFA."],
[4,"Which passwordless standard uses public-key cryptography with a hardware key or device biometric?","FIDO2/WebAuthn",["SMS one-time codes","Security questions","NTLM"],"FIDO2 is phishing-resistant because the key is bound to the real site."],
[4,"An analyst reviews why an incident happened so it doesn't recur. What is this?","Root cause analysis",["Threat hunting","E-discovery","Vulnerability scanning"],"Root cause analysis finds the underlying cause, not just the symptom."],
[4,"Which benchmark source provides widely used hardening guidance for operating systems and cloud platforms?","CIS Benchmarks",["CVE","CVSS","OWASP Top 10"],"CIS Benchmarks are consensus hardening guides."],
[4,"An employee's account is still active three months after they left. Which process failed?","Deprovisioning",["Provisioning","Federation","Attestation"],"Deprovisioning removes access promptly at offboarding."],
[5,"Which document type is mandatory and states what must be done, such as 'all laptops must be encrypted'?","Policy",["Guideline","Procedure","Recommendation"],"Policies are high-level and mandatory. Guidelines are optional advice. Procedures are step-by-step."],
[5,"Which document provides step-by-step instructions for resetting a user's MFA?","Procedure",["Policy","Standard","Guideline"],"Procedures describe exactly how to perform a task."],
[5,"Users must sign a document stating what they may and may not do on company systems. What is it?","Acceptable use policy",["Non-disclosure agreement","Service level agreement","Memorandum of understanding"],"The AUP defines acceptable use of IT resources."],
[5,"An asset worth $100,000 would lose 40% of its value in one incident. What is the single loss expectancy?","$40,000",["$100,000","$4,000","$60,000"],"SLE = asset value × exposure factor = 100,000 × 0.4."],
[5,"SLE is $40,000 and the incident is expected once every two years. What is the annualized loss expectancy?","$20,000",["$80,000","$40,000","$10,000"],"ALE = SLE × ARO = 40,000 × 0.5."],
[5,"Buying cyber insurance is which risk treatment?","Transfer",["Accept","Avoid","Mitigate"],"Transferring shifts the financial impact to a third party."],
[5,"A company stops offering a risky service entirely. Which risk strategy is this?","Avoid",["Transfer","Accept","Mitigate"],"Avoidance removes the activity that creates the risk."],
[5,"Management decides the cost of a control is higher than the potential loss and documents that decision. Which strategy is this?","Accept",["Avoid","Transfer","Mitigate"],"Acceptance is a conscious, documented decision."],
[5,"Which document lists identified risks, their owners, ratings and treatment status?","Risk register",["Risk appetite statement","Business impact analysis","SLA"],"The risk register tracks risks over time."],
[5,"Rating risks as High, Medium or Low without dollar amounts is which type of analysis?","Qualitative",["Quantitative","Inherent","Residual"],"Quantitative analysis uses numbers such as SLE and ALE."],
[5,"Which process identifies critical business functions and the impact of losing them?","Business impact analysis",["Risk register","Gap analysis","Vulnerability scan"],"A BIA sets RTO, RPO and priorities for recovery."],
[5,"Which metric measures the average time a repairable system runs before failing?","MTBF",["MTTR","RTO","RPO"],"Mean time between failures measures reliability. MTTR is the average time to repair."],
[5,"Which agreement defines measurable uptime and response times a vendor must meet?","Service level agreement",["Memorandum of understanding","Non-disclosure agreement","Statement of work"],"An SLA sets performance targets, often with penalties."],
[5,"Which contract clause lets a company inspect a vendor's security controls?","Right-to-audit clause",["Non-compete clause","Force majeure","Indemnification"],"Right-to-audit supports vendor oversight."],
[5,"Which agreement sets general terms for future work, with specific projects defined later in SOWs?","Master service agreement",["Memorandum of understanding","Business partners agreement","Service level agreement"],"The MSA is the umbrella contract; SOWs detail each engagement."],
[5,"A less formal document states the intent of two parties to work together, without strict legal penalties. What is it?","Memorandum of understanding",["Master service agreement","Service level agreement","Non-disclosure agreement"],"An MOU (or MOA) expresses mutual intent."],
[5,"Under GDPR, the company that decides why and how personal data is processed is the what?","Data controller",["Data processor","Data custodian","Data subject"],"The controller decides the purposes. The processor processes on the controller's behalf."],
[5,"Which GDPR right lets individuals request deletion of their personal data?","Right to be forgotten",["Right to audit","Data sovereignty","Legal hold"],"Also called the right to erasure."],
[5,"Which standard applies to organizations that store, process or transmit credit card data?","PCI DSS",["HIPAA","SOX","FERPA"],"The Payment Card Industry Data Security Standard."],
[5,"Penetration testers receive full network diagrams and source code. What type of test is this?","Known environment",["Unknown environment","Partially known environment","Passive reconnaissance"],"Formerly called white box. Unknown is black box; partially known is gray box."],
[5,"Testers gather employee names from social media and public records without touching the target's systems. What is this?","Passive reconnaissance (OSINT)",["Active reconnaissance","Vulnerability scanning","Fuzzing"],"Passive reconnaissance doesn't interact with the target directly."],
[5,"Which role is responsible for implementing and maintaining controls on data day-to-day, such as backups?","Data custodian",["Data owner","Data subject","Data controller"],"The owner is accountable and classifies data; the custodian handles it."],
[5,"Which role is ultimately accountable for a data set and decides its classification?","Data owner",["Data custodian","Data processor","System administrator"],"Owners are usually senior business leaders."],
[5,"The security team sends fake phishing emails to staff and tracks who clicks. What is this?","Phishing simulation campaign",["Penetration test","Watering hole attack","Tabletop exercise"],"Simulations measure and improve awareness."],
[5,"Leaders walk through a ransomware scenario in a conference room, discussing their responses without touching systems. What is this?","Tabletop exercise",["Failover test","Full simulation","Parallel processing test"],"Tabletops are discussion-based."],
[5,"An independent third party verifies and signs off that controls meet a standard. What is this?","External audit and attestation",["Internal self-assessment","Gap analysis by staff","Vulnerability scan"],"External audits provide independent assurance."],
[5,"The level of risk an organization is willing to accept in pursuit of its goals is called what?","Risk appetite",["Risk tolerance","Residual risk","Inherent risk"],"Appetite is the broad level; tolerance is the acceptable variation around it."],
[5,"Risk that remains after controls are applied is called what?","Residual risk",["Inherent risk","Risk appetite","Control risk"],"Inherent risk exists before controls; residual risk remains after."],
[5,"Which metric acts as an early warning that a risk is increasing, such as a rise in failed logins?","Key risk indicator",["Mean time to repair","Recovery point objective","Annualized rate of occurrence"],"KRIs track risk trends."],
[5,"Before signing a new cloud vendor, the company reviews its SOC 2 report and security questionnaire. What is this?","Vendor due diligence",["Risk transfer","Data sovereignty","Change management"],"Due diligence assesses third-party risk before engagement."],
[5,"Which agreement protects confidential information shared during business discussions?","Non-disclosure agreement",["Service level agreement","Acceptable use policy","Business partners agreement"],"An NDA legally binds parties to secrecy."],
[5,"Security decisions are made by a central team that sets policy for all business units. What governance structure is this?","Centralized",["Decentralized","Federated by default","Ad hoc"],"Centralized governance offers consistency; decentralized offers flexibility."],
[5,"What is the main purpose of security awareness training?","To reduce human-driven risk by changing user behavior",["To replace technical controls","To meet only legal requirements","To train staff to perform penetration tests"],"Training targets phishing, password hygiene, reporting and insider risk."]],"lessons":{"1":[["Control categories and types","Categories: Technical (firewalls, encryption), Managerial (policies, risk assessments), Operational (guards, training done by people), Physical (locks, fences).|Types: Preventive (stop it), Deterrent (discourage it), Detective (find it), Corrective (fix it), Compensating (alternative protection), Directive (tell people what to do).|One control can be several things: a guard is physical, preventive and deterrent.","Questions often give a control and ask for its type. Ask yourself: does it stop, discourage, detect, fix or substitute?"],
["CIA, non-repudiation and AAA","Confidentiality: only authorized people see data (encryption, access control).|Integrity: data isn't altered (hashing, digital signatures).|Availability: systems are up when needed (redundancy, backups).|Non-repudiation: the sender can't deny the action (digital signatures).|AAA: Authentication (who are you), Authorization (what can you do), Accounting (what did you do).","Hashing alone gives integrity, not non-repudiation. A signature adds identity."],
["Zero Trust and physical security","Never trust, always verify. Every request is checked, regardless of network location.|Control plane: Policy Engine decides, Policy Administrator relays.|Data plane: Policy Enforcement Point allows or blocks; subjects and resources live here.|Adaptive identity, threat scope reduction and microsegmentation are core ideas.|Physical: bollards, vestibules, fencing, lighting, guards, cameras, sensors (infrared, pressure, microwave, ultrasonic).","Remember PE decides, PEP enforces."],
["Deception and change management","Honeypot (fake system), honeynet (fake network), honeyfile (fake file), honeytoken (fake credential or record).|Change management: approval, ownership, stakeholders, impact analysis, test results, backout plan, maintenance window, SOP.|Technical side: allow and deny lists, restricted activities, downtime, service restarts, legacy apps, dependencies, documentation and version control.","Any unplanned change is a risk. A backout plan is required before production changes."],
["Cryptography essentials","Symmetric: one shared key, fast (AES, ChaCha20). Asymmetric: key pair (RSA, ECC), used for key exchange and signatures.|Hashing: one-way fixed output (SHA-256). Salting defeats rainbow tables. Key stretching (bcrypt, PBKDF2) slows guessing.|Encrypt for a recipient with their public key. Sign with your own private key.|Diffie-Hellman/ECDHE create shared secrets. Ephemeral keys give perfect forward secrecy.|Obfuscation: steganography, tokenization, data masking.","Know which key does what. It is the most-tested crypto concept."],
["PKI and crypto hardware","CA issues certificates; a CSR requests one. Root CA, intermediate CA, chain of trust.|Revocation: CRL (list) and OCSP (real-time); OCSP stapling puts the response in the TLS handshake.|Wildcard (*.domain) vs SAN (multiple named hosts). Self-signed certificates are not trusted by default.|TPM: chip in the device. HSM: dedicated appliance. Secure enclave: isolated processor area. KMS: cloud key management.|Key escrow: a trusted third party holds a copy of keys.","TPM is inside one device. HSM serves many at scale."]],"2":[["Threat actors and motivations","Nation-state/APT: high resources, espionage, persistence.|Organized crime: financial gain (ransomware, fraud).|Hacktivist: ideology. Insider: access and grievance or money. Unskilled attacker: uses others' tools. Shadow IT: unapproved tech.|Attributes: internal or external, resources and funding, sophistication.|Motivations: data exfiltration, espionage, disruption, blackmail, financial gain, revenge, war.","Match the motive in the scenario to the actor."],
["Social engineering","Phishing (email), spear phishing (targeted), whaling (executives), vishing (voice), smishing (SMS).|Pretexting (invented story), impersonation, BEC (business email compromise), watering hole, typosquatting, brand impersonation, misinformation.|Principles attackers use: authority, urgency, scarcity, familiarity, trust, social proof.","Spot the channel (email, voice, SMS) and the target (anyone, specific person, executive)."],
["Malware types","Ransomware, Trojan, worm (self-spreading), virus (needs a host), spyware, keylogger, rootkit (hides deep), logic bomb (condition-triggered), bloatware, fileless (memory/PowerShell).|Indicators: account lockouts, concurrent sessions, blocked content, impossible travel, resource consumption, missing logs, out-of-cycle logging.","Worm = no user action. Logic bomb = waits for a condition."],
["Application and web attacks","Injection (SQL, LDAP, command): fix with parameterized queries and input validation.|XSS runs script in the victim's browser. CSRF forces actions using the victim's session. SSRF makes the server send requests.|Buffer overflow, race condition (TOCTOU), directory traversal, privilege escalation, memory injection.|Mitigate: input validation, output encoding, least privilege, patching, WAF, secure coding.","' OR 1=1 = SQLi. <script> = XSS. ../ = traversal."],
["Network and password attacks","On-path, ARP poisoning, DNS poisoning, MAC flooding, DDoS (amplified and reflected), replay, downgrade, evil twin, rogue AP, Bluetooth attacks.|Passwords: brute force, dictionary, spraying (one password, many users), stuffing (breached pairs), rainbow tables, pass-the-hash.|Crypto: birthday (collision), downgrade.","Spraying avoids lockouts. Stuffing exploits password reuse."],
["Vulnerabilities and mitigations","Types: OS, application, web, hardware/firmware, end-of-life, legacy, virtualization (VM escape, resource reuse), cloud, supply chain, misconfiguration, mobile (sideloading, jailbreaking), zero-day.|Mitigations: segmentation, access control and least privilege, application allow lists, isolation, patching, encryption, monitoring, configuration enforcement, decommissioning, hardening.","A legacy system you cannot patch calls for compensating controls such as isolation."]],"3":[["Cloud and architecture models","IaaS (you manage the OS and up), PaaS (you manage the app and data), SaaS (you manage users and data).|Shared responsibility: the provider always handles the physical layer.|Serverless, microservices, containers, IaC, SDN, hybrid and multi-cloud, centralized vs decentralized.|On-prem, air-gapped, ICS/SCADA, RTOS, embedded, IoT: often hard to patch.","As you move from IaaS toward SaaS, the provider handles more."],
["Network infrastructure","Zones: screened subnet (DMZ), intranet, extranet. Attack surface and connectivity.|Devices: jump server, forward and reverse proxy, load balancer, WAF, NGFW, UTM, IDS (passive) and IPS (inline), sensors.|Fail-open (availability) vs fail-closed (security).|Secure access: VPN (IPsec tunnel vs transport, TLS), 802.1X/EAP, SD-WAN, SASE.","WAF = layer 7 web protection. IPS blocks; IDS alerts."],
["Protecting data","States: at rest, in transit, in use.|Classification: public, internal, confidential, restricted, sensitive, critical.|Methods: encryption, hashing, masking, tokenization, obfuscation, segmentation, permission restrictions, geographic restrictions.|Data sovereignty: data follows the laws of where it is stored.","Masking hides on screen. Tokenization swaps with a vault-mapped value."],
["Resilience and recovery","High availability: load balancing, clustering, active-active vs active-passive.|Sites: hot (ready now), warm (needs data), cold (empty space). Geographic dispersion and platform diversity.|Backups: full, incremental (since last backup), differential (since last full), snapshots, replication, journaling, encryption, off-site.|Power: UPS (short-term), generator (long-term).|Testing: tabletop, failover, simulation, parallel processing.","RPO = how much data you can lose. RTO = how fast you must be back."]],"4":[["Hardening and secure baselines","Establish, deploy and maintain baselines (CIS benchmarks).|Harden: mobile, workstations, switches, routers, cloud, servers, ICS, embedded, IoT. Remove defaults, close ports, patch.|Mobile: MDM, BYOD, COPE, CYOD.|Wireless: WPA3 (SAE), 802.1X with RADIUS, EAP-TLS. Site surveys and heat maps.|App security: input validation, secure cookies, static analysis, code signing, sandboxing.","WPA3 SAE replaces PSK. EAP-TLS needs certificates on both sides."],
["Assets and vulnerability management","Asset lifecycle: acquisition, assignment and ownership, inventory, disposal (sanitize, destroy, certificate of destruction, data retention).|Find flaws: vulnerability scans (credentialed or not), application testing, threat feeds (OSINT, dark web), pen tests, bug bounties.|Analyze: CVE (ID), CVSS (score), false positives and negatives, prioritization, exposure factor, risk tolerance.|Respond: patch, insurance, segmentation, compensating controls, exceptions. Validate with a rescan.","Credentialed scans see more. A false negative is the dangerous one."],
["Monitoring and security tools","SIEM (aggregate and correlate), SOAR (automate playbooks), DLP, NetFlow, SNMP traps, vulnerability scanners, antivirus, EDR/XDR, UBA, FIM.|Email: SPF (authorized senders), DKIM (signature), DMARC (policy and reporting).|Network: firewall rules and ACLs, IDS/IPS signatures, web and DNS filtering.|Secure protocols: SSH 22, HTTPS 443, LDAPS 636, SFTP, SNMPv3, DNSSEC.","SIEM sees. SOAR does."],
["Identity and access management","Provisioning and deprovisioning, identity proofing, federation, SSO (SAML, OAuth, OpenID Connect, LDAP).|Access models: RBAC (roles), ABAC (attributes), MAC (labels), DAC (owner decides), rule-based, time-of-day.|MFA factors: know, have, are, somewhere you are. TOTP, HOTP, FIDO2 passwordless.|PAM: just-in-time, password vaulting, ephemeral credentials.","SAML = authentication with XML. OAuth = authorization with tokens."],
["Incident response and forensics","Process: preparation, detection, analysis, containment, eradication, recovery, lessons learned.|Training, testing (tabletop, simulation), root cause analysis, threat hunting.|Forensics: legal hold, chain of custody, acquisition, reporting, preservation, e-discovery.|Order of volatility: CPU registers and cache, RAM, swap, disk, remote logs, archives.|Data sources: firewall, application, endpoint, OS and network logs, metadata, packet captures, dashboards.","Contain before you eradicate. Capture RAM before you power off."]],"5":[["Governance documents","Policies (mandatory, high-level): AUP, information security, BC/DR, IR, SDLC, change management.|Standards (specific requirements: passwords, encryption). Procedures (step-by-step). Guidelines (recommended).|Governance structures: boards, committees, government entities, centralized vs decentralized.|Roles: data owner (accountable), controller, processor, custodian or steward.","Policy says what. Procedure says how. Guideline suggests."],
["Risk management","Identify, assess, analyze. Qualitative (High/Med/Low) vs quantitative.|SLE = AV × EF. ALE = SLE × ARO.|Treatments: transfer, accept (exemption, exception), avoid, mitigate.|Risk register, KRIs, risk owner, risk threshold, appetite (expansionary, conservative, neutral) vs tolerance.|BIA: RTO, RPO, MTTR, MTBF.","Practice the ALE math. It shows up reliably."],
["Third-party risk","Vendor assessment: pen tests, right-to-audit, evidence of internal audits, independent assessments, supply chain analysis.|Selection: due diligence, conflict of interest.|Agreements: SLA (performance), MOA/MOU (intent), MSA (umbrella), WO/SOW (specific work), NDA (secrecy), BPA (partnership).|Ongoing monitoring and questionnaires; rules of engagement.","SLA = measurable service levels. MSA = umbrella contract."],
["Compliance, audits and awareness","Compliance reporting (internal and external); consequences include fines, sanctions, loss of license, reputational damage.|Privacy: data subject, controller vs processor, right to be forgotten, data inventory and retention.|Audits: attestation, internal (compliance, audit committee, self-assessments), external (regulatory, independent).|Pen testing: physical, offensive, defensive, integrated; known, partially known or unknown environment. Recon: passive vs active.|Awareness: phishing campaigns, anomalous behavior recognition, user guidance, reporting and monitoring.","Known environment = full info given. Unknown = no info."]]},"scen":[{"id":"ransom","dom":4,"title":"Ransomware at 2:14 AM","intro":"You are the on-call security analyst at a regional hospital. Your phone buzzes with a SIEM alert.","steps":[{"log":["02:14:07 EDR  [warn] WS-NURSE-12 vssadmin.exe delete shadows /all /quiet","02:14:09 EDR  [alert] WS-NURSE-12 mass file rename *.docx -> *.locked","02:14:22 SIEM [alert] SMB writes from WS-NURSE-12 to \\\\FS01\\shared spiking","02:14:30 FS01 [warn] 3,812 files modified in 23 seconds"],"say":"An endpoint is deleting shadow copies and renaming files. It is now writing to the main file server. What is your first action?","choices":[["Isolate WS-NURSE-12 from the network using EDR",1,"Correct. Containment comes first. Isolating the host stops encryption spreading to FS01."],
["Reimage the workstation right away",0,"Too early. Reimaging destroys evidence and the infection may already be spreading. Contain first."],
["Email all staff to warn them",0,"Communication matters, but it does not stop the active encryption. Contain the host first."]]},{"log":["02:16:40 EDR  [ok] WS-NURSE-12 network isolated","02:17:02 FS01 [warn] file modifications stopped","02:17:30 IR   ticket INC-4471 opened","02:18:11 EDR  [info] parent process: invoice_0419.pdf.exe from Outlook temp"],"say":"Spread has stopped. The malware came from an email attachment. Before wiping anything, what should you capture?","choices":[["A memory image of the host, then the disk image",1,"Correct. Order of volatility: RAM before disk. Memory may hold encryption keys and process details."],
["Only the ransom note screenshot",0,"Not enough evidence. Capture volatile memory, then disk, and maintain chain of custody."],
["Nothing; restore from backup",0,"Skipping evidence prevents root cause analysis and could break legal or regulatory duties."]]},{"log":["02:41:55 FOR  [ok] memory image acquired, SHA-256 recorded","02:58:10 FOR  [ok] disk image acquired, chain of custody form #22","03:05:00 MAIL [info] 14 other users received invoice_0419.pdf.exe"],"say":"Fourteen other users got the same email. How do you remove the threat across the environment?","choices":[["Purge the email from all mailboxes and block the hash and sender",1,"Correct. This is eradication. Remove the source and block indicators everywhere."],
["Wait to see if other hosts trigger alerts",0,"Waiting risks more infections. Act on known indicators now."],
["Pay the ransom to get the key quickly",0,"Paying funds criminals, doesn't guarantee recovery and may be illegal. Restore from clean backups."]]},{"log":["06:30:00 BKP  [ok] FS01 restored from 01:00 snapshot (RPO 1h met)","08:00:00 IR   lessons-learned meeting scheduled","08:05:00 IR   action: attachment sandboxing, macro and EXE blocking"],"say":"Files are restored and services are back. What is the final phase of the incident response process?","choices":[["Lessons learned and update controls",1,"Correct. Review what happened, find the root cause and improve defenses and the IR plan."],
["Close the ticket with no review",0,"Skipping lessons learned means the same attack can work again."],
["Begin preparation for a new audit",0,"Preparation is the first phase. The incident still needs a lessons-learned review."]]}]},{"id":"bec","dom":2,"title":"The urgent wire transfer","intro":"You work on the finance security team. Accounts payable forwards a suspicious email.","steps":[{"log":["From: \"Mark Ellis, CEO\" <mark.ellis@contoso-corp.co>","To: ap-lead@contoso.com","Subject: URGENT - confidential acquisition payment","Body: Wire $184,500 today. Do not discuss. I am in meetings, email only."],"say":"The email claims to come from the CEO and demands an urgent, secret wire. What attack is this most likely?","choices":[["Business email compromise using a look-alike domain",1,"Correct. The domain contoso-corp.co is not contoso.com, and urgency plus secrecy are classic BEC signs."],
["A legitimate request; process it",0,"Never pay on email alone. Verify through a known phone number."],
["Smishing",0,"Smishing uses SMS. This arrived by email."]]},{"log":["SPF:   none (contoso-corp.co)","DKIM:  none","DMARC: contoso.com policy p=none","Registrar: contoso-corp.co created 2 days ago"],"say":"Your own domain's DMARC policy is set to none. What change best helps stop spoofing of your real domain?","choices":[["Move DMARC to quarantine, then reject, after SPF and DKIM are aligned",1,"Correct. An enforcing DMARC policy tells receivers to block mail that fails authentication."],
["Disable SPF",0,"SPF is part of the defense. Disabling it makes spoofing easier."],
["Turn off DKIM to speed delivery",0,"DKIM signs your mail. Keep it on."]]},{"log":["AP team: phoned CEO at directory number -> request denied","Payment: NOT sent","Ticket: block domain contoso-corp.co at mail gateway"],"say":"The payment was stopped by calling the CEO. Which control should become mandatory policy?","choices":[["Out-of-band verification for any payment or bank-detail change",1,"Correct. A call-back to a known number defeats most BEC attempts."],
["Faster wire approvals for executives",0,"Speed is what attackers exploit. Add verification, not shortcuts."],
["Allow wires approved by email reply",0,"Email can be spoofed or compromised. Use a separate channel."]]}]},{"id":"sqli","dom":2,"title":"Strange login traffic","intro":"You monitor the customer portal of an online retailer. The WAF is in detection-only mode.","steps":[{"log":["10:02:11 WAF [warn] POST /login user=admin'-- pass=x","10:02:14 WAF [warn] POST /login user=' OR '1'='1 pass=x","10:02:15 APP [info] login success user_id=1 (admin)","10:02:40 APP [warn] GET /admin/export?table=customers"],"say":"An attacker logged in as admin without a valid password. What vulnerability was exploited?","choices":[["SQL injection",1,"Correct. The quote and OR 1=1 logic changed the login query."],
["Cross-site scripting",0,"XSS injects script into a browser. This changed a database query."],
["Brute force",0,"Only two attempts, both with SQL syntax. That's injection, not guessing."]]},{"log":["10:03:05 WAF mode: detection-only","10:03:06 DB  [alert] SELECT * FROM customers -> 48,211 rows"],"say":"Data is being exported now. What is the best immediate action?","choices":[["Switch the WAF to blocking and disable the admin session",1,"Correct. Contain the active attack: block the payloads and kill the attacker's session."],
["Start a code review next sprint",0,"A long-term fix is needed, but the attack is happening now. Contain first."],
["Delete the customers table",0,"Destroying data harms the business and evidence. Contain the attacker instead."]]},{"log":["10:05:00 WAF [ok] blocking enabled","10:05:02 APP [ok] session revoked for user_id=1","10:30:00 DEV ticket: fix /login query"],"say":"Which code fix permanently prevents this flaw?","choices":[["Parameterized queries (prepared statements)",1,"Correct. User input is treated as data, never as SQL code."],
["Hide error messages",0,"That helps against reconnaissance but doesn't stop injection."],
["Use HTTPS",0,"HTTPS protects data in transit, not query logic."]]}]},{"id":"insider","dom":4,"title":"The departing engineer","intro":"HR tells you a senior engineer resigned yesterday and is joining a competitor.","steps":[{"log":["DLP  [alert] j.rivera uploaded design_specs.zip (2.3 GB) to personal cloud","PROXY [info] destination: personal-drive storage","AD   [info] j.rivera account active, VPN access active","TIME 23:48 (outside normal hours)"],"say":"Large uploads to personal cloud storage, late at night, after resignation. Which threat is this?","choices":[["Insider threat performing data exfiltration",1,"Correct. A legitimate user with access is moving data out, which is a classic insider risk."],
["Nation-state APT",0,"Possible in theory, but the evidence points to the departing employee."],
["False positive; ignore it",0,"Several strong indicators line up. Investigate."]]},{"log":["Legal: preserve all of j.rivera mail and files","HR: termination meeting 09:00"],"say":"Legal wants all of this user's data preserved for possible litigation. What is this called?","choices":[["Legal hold",1,"Correct. A legal hold suspends normal deletion and preserves relevant data."],
["Data sanitization",0,"Sanitization destroys data, the opposite of what Legal needs."],
["Tokenization",0,"Tokenization protects data values. It is not a preservation process."]]},{"log":["09:00 HR meeting started","09:00 IAM disable account, revoke VPN, revoke tokens","09:01 MDM wipe corporate container on phone"],"say":"Which process should run at the moment of termination?","choices":[["Deprovisioning: disable accounts and revoke all access",1,"Correct. Remove access right away so no more data can leave."],
["Provisioning new access for the replacement",0,"Useful later, but the priority is cutting off the departing user."],
["Wait 30 days per retention policy",0,"Access removal must be immediate. Retention applies to data, not access."]]}]},{"id":"laptop","dom":3,"title":"Laptop left in a taxi","intro":"A sales manager calls: their company laptop was left in a taxi an hour ago.","steps":[{"log":["MDM  device: SALES-LT-077 last check-in 47 min ago","BitLocker: enabled, TPM+PIN","Data: CRM exports, customer contact lists"],"say":"The laptop is encrypted with BitLocker using a TPM and PIN, and it's powered off. Which data state does this protect?","choices":[["Data at rest",1,"Correct. Full-disk encryption protects stored data when the device is off or locked."],
["Data in transit",0,"In transit means moving across a network. TLS and VPNs protect that."],
["Data in use",0,"Data in use is in memory while the device runs."]]},{"log":["MDM  remote lock: queued","MDM  remote wipe: available","IAM  user sessions: 3 active (email, CRM, VPN)"],"say":"What should you do with the user's active cloud sessions?","choices":[["Revoke the sessions and reset credentials",1,"Correct. Cached tokens could let someone in even without the password."],
["Leave them; the disk is encrypted",0,"Encryption protects the disk, but live tokens in apps can still be abused if the device is unlocked."],
["Disable MFA for faster re-login",0,"Never weaken MFA during an incident."]]},{"log":["MDM  remote wipe: sent (will execute on next check-in)","Ticket: report to privacy officer for breach assessment"],"say":"Because the disk was encrypted, is this likely a reportable data breach?","choices":[["Usually not, since encrypted data is generally treated as protected, but the privacy officer must assess it",1,"Correct. Many regulations provide safe harbor for strong encryption, but follow your process."],
["Yes, always notify all customers immediately",0,"Notification rules depend on regulation and whether data was actually exposed."],
["No need to report internally",0,"Always report through the incident process so the right people can decide."]]}]},{"id":"ddos","dom":3,"title":"Black Friday traffic flood","intro":"It's the biggest sales day of the year. The storefront is slowing to a crawl.","steps":[{"log":["11:00 LB   [warn] requests/sec 210,000 (normal 9,000)","11:00 FW   [warn] UDP 53 inbound 9.8 Gbps from 41,000 IPs","11:01 APP  [alert] p95 latency 14,200 ms","11:01 NET  [info] responses are large DNS ANY replies"],"say":"Huge DNS responses arrive from thousands of open resolvers. What type of attack is this?","choices":[["Amplified reflection DDoS",1,"Correct. The attacker spoofs your IP so open resolvers flood you with large responses."],
["SQL injection",0,"This is a volume attack on availability, not an application query flaw."],
["ARP poisoning",0,"ARP poisoning is a local network attack, not internet-wide flooding."]]},{"log":["11:05 ISP  scrubbing service available","11:05 CDN  DDoS protection: not enabled"],"say":"Which response restores availability fastest?","choices":[["Engage ISP or cloud DDoS scrubbing and enable CDN protection",1,"Correct. Volumetric attacks must be filtered upstream before they reach your link."],
["Add a rule on the local firewall only",0,"The link is already saturated before traffic reaches your firewall."],
["Restart the web servers",0,"Restarting doesn't stop the flood."]]},{"log":["11:20 ISP  [ok] scrubbing active","11:21 APP  [ok] p95 latency 310 ms","Postmortem: add always-on DDoS protection and active-active regions"],"say":"Which design change improves resilience for next year?","choices":[["Active-active load-balanced sites in different regions",1,"Correct. Geographic dispersion and high availability absorb failures and attacks."],
["A single, larger server",0,"That is a single point of failure."],
["A cold site",0,"A cold site takes days to bring up, which is far too slow for e-commerce."]]}]}]};
